(function(root){
'use strict';
// Integrated Science 6–10: one lesson per instructional segment of the 2016 California Science Framework
// (grades 6–8, Preferred Integrated Course Model; then Living Earth and Chemistry in the Earth System).
// The plan is review/integrated-science-plan-20261115.md. Units are added one pull request at a time.
const clone=x=>JSON.parse(JSON.stringify(x));
const range=(name,label,min,max,step=1)=>({name,label,min,max,step});
const pick=(name,label,options)=>({name,label,options});
const st=(title,text,predict,test,explain,hint='')=>({title,text,try:[predict,test,explain].join(' '),activity:{predict,test,explain,hint}});
const q=(prompt,correct,wrong1,wrong2,explanation)=>({prompt,labels:[correct,wrong1,wrong2],explanation});
const UNITS=[
 {id:'grade-6',title:'Grade 6',topic:'Systems in organisms and Earth’s climate'},
 {id:'grade-7',title:'Grade 7',topic:'Matter, Earth’s resources and ecosystems'},
 {id:'grade-8',title:'Grade 8',topic:'Forces, space, evolution and waves'}
];
const SPECS=[
 {unit:'grade-6',segment:'Grade 6, instructional segment 1',pe:['MS-LS1-1','MS-LS1-2','MS-LS1-3'],
  short:'Cells as systems',title:'Why are cells so small?',goal:'Relate a cell’s size to how quickly materials can cross its surface, and see a body as systems built from cells.',
  defaults:{side:10,shape:'cube'},controls:[range('side','Side length of the model cell (µm)',2,20),pick('shape','Shape',[['cube','Cube'],['flat','Flat slab, a quarter as thick as it is wide']])],
  steps:[
   st('Every living thing is made of cells.','Cell theory has three parts: all living things are made of one or more cells; the cell is the basic unit of structure and function; and new cells come only from existing cells. Most cells are too small to see without a microscope. Many animal cells are 10 to 30 micrometers (µm) across, and a typical bacterium is about 1 to 2 µm long. Inside a cell, the nucleus directs its work and mitochondria release energy from food; plant cells also have chloroplasts and a cell wall.','Is a bigger cell always a better cell?','Set the model cell to 5 µm, then to 10 µm, and read its volume.','Describe how volume grows when the side length doubles.'),
   st('A cell trades through its surface.','Oxygen and food molecules enter, and wastes leave, through the cell membrane. What a cell needs grows with its volume, side³ for a cube. What can cross grows with its surface area, 6 × side². The surface-area-to-volume ratio compares the two: for a cube it is 6/side.','For a 10 µm cube, how many square micrometers of surface does it have for each cubic micrometer of volume?','Read both values at 10 µm, then compute 6/10.','Explain what the ratio 0.6 per µm means for this cell.'),
   st('Bigger cells fall behind.','When the side doubles, volume becomes 8 times as large but surface area only 4 times, so the ratio halves. A large cell would need more than its surface can deliver. Large organisms are made of many small cells, not a few giant ones.','If a cube-shaped cell grows from 5 µm to 20 µm, what happens to its ratio?','Compare the ratio at 5 µm and at 20 µm.','Use the ratio to explain why cells divide instead of growing without limit.'),
   st('Shape and systems help.','A flat shape keeps more surface for its volume. Bodies use the same idea at larger scales. Groups of similar cells form tissues, tissues form organs, and organs work together as systems. The small intestine is lined with folds and tiny projections called villi, and the lungs hold hundreds of millions of air sacs. The digestive, respiratory and circulatory systems work together to bring materials close to every cell.','A cube and a flat slab hold about the same volume. Which has more surface for each cubic micrometer?','Compare a 6 µm cube with a 10 µm slab: read the volume and the ratio of each.','Name two body systems that must work together to bring oxygen to a muscle cell, and say what each does.','Read the volumes first, so you compare cells of about the same size.')
  ],questions:[
   q('A cube-shaped cell’s side doubles from 10 µm to 20 µm. What happens to its surface-area-to-volume ratio?','It is halved, from 0.6 to 0.3 per µm.','It doubles, from 0.6 to 1.2 per µm.','It stays the same, because the cell keeps its shape.','For a cube the ratio is 6/side, so doubling the side halves it. Volume grows 8 times while surface area grows only 4 times.'),
   q('Which statement is part of cell theory?','All living things are made of one or more cells.','All cells are the same size and shape.','Cells can form from nonliving matter.','Cell theory says that all living things are made of cells, that the cell is the basic unit of life, and that new cells come from existing cells. Cells vary widely in size and shape.'),
   q('Oxygen in the lungs must reach a muscle cell in the leg. Which body systems must interact?','The respiratory system and the circulatory system','The digestive system and the skeletal system','The nervous system alone','The respiratory system brings oxygen into the lungs, and the circulatory system carries it in the blood to every cell.')],
  next:'Look at onion-skin or cheek cells under a microscope, estimate one cell’s size from the field of view, and work out its surface-area-to-volume ratio as if it were a cube.'},
 {unit:'grade-6',segment:'Grade 6, instructional segment 2',pe:['MS-PS3-4','MS-PS3-5','MS-ESS2-4'],
  short:'Heating ice',title:'Heating ice: where does the energy go?',goal:'Read a heating curve, and explain why temperature stops rising while ice melts and water boils.',
  defaults:{mass:200,energy:0},controls:[range('mass','Mass of ice (g)',100,500,50),range('energy','Energy added (kJ)',0,800,5)],
  steps:[
   st('Energy in, temperature up?','The sample starts as ice at −20 °C, heated slowly and stirred. At first, every kilojoule added raises the temperature: the water molecules in the ice vibrate faster.','Will the temperature keep rising steadily as energy is added?','Set the mass to 500 g and add energy 5 kJ at a time up to 20 kJ, reading the temperature each time.','Describe the first part of the graph in words.'),
   st('The flat parts.','At 0 °C the temperature stops rising until all the ice has melted. The added energy breaks the arrangement that holds the molecules in a solid instead of speeding them up. Melting 1 g of ice takes about 334 J. At 100 °C there is a second, much longer flat part while water boils.','Which flat part is longer: melting or boiling?','Move the energy across the whole range and compare the two flat parts.','Use the numbers in the table to explain the difference in length.'),
   st('More mass needs more energy.','Warming water takes about 4.18 J per gram per degree. The energy needed for a change is mass × 4.18 × change in temperature, so twice the mass needs twice the energy for the same change.','Will 400 g of water need more, less or the same energy as 200 g to warm by 10 °C?','Compare the length of the sloping water part at 200 g and at 400 g.','Explain the difference using the formula energy = mass × 4.18 × temperature change.'),
   st('Water carries energy into the sky.','Turning 1 g of boiling water into steam takes about 2,256 J, nearly seven times the energy needed to melt it. Evaporating water from a cooler ocean takes a little more, about 2,440 J per gram at 25 °C, and sunlight supplies it. When the water vapor rises and condenses into clouds, the same energy is released and warms the air. Gravity then pulls the rain and snow back down. This is one way the water cycle moves energy around Earth and drives weather.','Does a cloud forming warm or cool the air around it?','Set the mass back to 200 g, find the boiling plateau and read how much energy it holds.','Explain how energy taken in at the sea surface can be released high in the atmosphere.','The boiling plateau stands for about the same energy that evaporation takes in at lower temperatures; a little more is needed when the water is cooler.')
  ],questions:[
   q('A glass of ice water at 0 °C is stirred and warmed gently until half of the ice has melted. What does a thermometer in the water show?','It stays at about 0 °C.','It rises steadily the whole time.','It falls below 0 °C.','While ice and liquid water are both present and stirred, the added energy melts ice instead of raising the temperature.'),
   q('Warming 200 g of water by 10 °C takes about 8.4 kJ. About how much does warming 400 g of water by 10 °C take?','About 16.7 kJ','About 8.4 kJ','About 4.2 kJ','Energy = mass × 4.18 J/(g·°C) × temperature change = 400 × 4.18 × 10 ≈ 16,700 J. Doubling the mass doubles the energy.'),
   q('Why does water vapor condensing into a cloud warm the air around it?','Condensing releases the energy that evaporation took in.','Clouds are closer to the Sun.','New hot particles are created inside the cloud.','Evaporation takes in about 2,260 to 2,500 J for each gram, more when the water is cooler; condensation gives the same energy back to the surrounding air.')],
  next:'With an adult, heat crushed ice in a beaker on a hot plate, record the temperature every 30 seconds while stirring, and compare your graph’s flat part with the model.'},
 {unit:'grade-6',segment:'Grade 6, instructional segment 3',pe:['MS-ESS2-5','MS-ESS2-6','MS-LS1-5'],
  short:'Rain shadows',title:'Why is one side of the mountains wetter?',goal:'Follow air over a mountain range to explain a rain shadow, and connect regional climate to the living things found there.',
  defaults:{temperature:20,dewPoint:12,height:3},controls:[range('temperature','Air temperature at the coast (°C)',10,30),range('dewPoint','Dew point at the coast (°C)',0,20),range('height','Height of the mountain range (km)',0.5,4,0.5)],
  steps:[
   st('Rising air cools.','At California’s latitude, uneven heating of Earth and its rotation make winds blow mostly from the west. In winter, storms carry moist air masses from the Pacific east, up the western slopes of the Sierra Nevada. As air rises, the pressure around it drops, it expands and it cools. Air without clouds cools by about 10 °C for every kilometer it rises.','Air at 20 °C rises 1 km before any cloud forms. About how warm is it then?','Set the range to 1 km and the dew point to 0 °C, so no cloud forms, and read the temperature at the crest.','Explain why rising air cools even though no heat is taken from it.'),
   st('Clouds form at the dew point.','The dew point is the temperature at which the air’s water vapor starts to condense; a lower dew point means the air holds less water vapor. Rising air cools faster than its dew point falls, so the two meet at the cloud base: about 125 m higher for each degree between the temperature and the dew point at the ground. Inside the cloud, condensation releases energy, so the air cools more slowly, about 5 °C per kilometer in this model.','Will a bigger gap between temperature and dew point give a higher or lower cloud base?','Keep the temperature at 20 °C and change the dew point from 16 °C to 8 °C.','Explain the cloud-base heights you read.'),
   st('Rain on one side, dry air on the other.','Above the cloud base the air rains or snows out much of its water on the windward slope, the side facing the wind. Coming down the leeward side, facing away from the wind, the air has no cloud left and warms by 10 °C per kilometer all the way down. If a cloud formed on the way up, the air arrives warmer and drier than it started: a rain shadow. Owens Valley and the deserts east of the Sierra Nevada lie in one.','A cloud formed on the way up. Will the air be warmer, cooler or the same at the bottom of the far side?','Set the coast to 20 °C with a dew point of 12 °C, then compare the far-side temperature for ranges of 1, 2 and 3 km.','Use the cooling rates to explain why the far side is warmer when a cloud forms, and the same when none does.'),
   st('Living things fit their climate.','Regional climate shapes what grows where. Giant sequoias grow naturally only on the wetter western slopes of the Sierra Nevada, mostly between about 1,500 and 2,100 m. East of the range, desert plants such as creosote bush have small, waxy leaves that lose little water. How well an organism grows depends on its genes and on local conditions such as water, light and temperature: in a dry year, the same plant grows less.','Which side of the range would you expect to have taller forests?','Set a 3 km range and compare the dew point at the coast with the dew point on the far side.','Give one plant structure that helps in a dry climate and explain how it helps.')
  ],questions:[
   q('Moist air from the Pacific blows east over the Sierra Nevada. Where is rain or snow more likely?','On the western, windward slopes','On the eastern, leeward side','Equally on both sides','Air rising up the western slopes cools to its dew point, forms clouds and loses water. Sinking air on the eastern side warms and dries.'),
   q('Air at 20 °C rises 1.5 km without forming a cloud. About what is its temperature now?','About 5 °C','About 18.5 °C','About −10 °C','Air without clouds cools about 10 °C per kilometer: 20 − 10 × 1.5 = 5 °C.'),
   q('Why is air that comes down the far side of a mountain range drier than when it started up?','Much of its water fell as rain or snow on the way up.','Sinking air gains water vapor.','The mountains absorb water vapor directly from the air.','The water that condensed and fell on the windward slope is gone, so the descending air holds less water vapor.')],
  next:'Find average yearly rainfall for a coastal city, a city on the western Sierra slope and a town in Owens Valley, and explain the pattern with the cooling rates from this lesson.'},
 {unit:'grade-6',segment:'Grade 6, instructional segment 4',pe:['MS-ESS3-5','MS-LS1-5'],
  short:'Global warming',title:'Why does more carbon dioxide warm the planet?',goal:'Use an energy balance to explain why adding carbon dioxide warms Earth, and how much a doubling might warm it.',
  defaults:{co2:426},controls:[range('co2','Carbon dioxide in the air (parts per million)',278,1112,2)],
  steps:[
   st('Energy in, energy out.','Thermometer records on land and at sea show that Earth’s average surface temperature has risen about 1.2 °C since the late 1800s, with ups and downs from year to year; land has warmed faster than the ocean, and the Arctic fastest. To ask what causes it, start with energy. Earth absorbs sunlight and sends energy back to space as infrared light. When the energy going out each second equals the energy coming in, the average temperature stays steady. This is an energy balance.','If more energy comes in than goes out, what happens to Earth’s temperature?','Set carbon dioxide to 278 ppm, the level before industry, and read the extra energy kept.','Explain what “balance” means for Earth’s temperature.'),
   st('Carbon dioxide holds some infrared back.','Carbon dioxide and other greenhouse gases absorb infrared light from the surface and send part of it back down. With more of them, less energy escapes at the same temperature, so Earth keeps extra energy each second until it warms up. The lab measures that extra energy in watts per square meter (W/m²): joules each second for each square meter of Earth.','Does adding carbon dioxide change the sunlight coming in, or the infrared going out?','Raise carbon dioxide from 278 ppm to 426 ppm and read the extra energy kept.','Explain why Earth warms after the extra energy is kept.'),
   st('Warming until balance returns.','A warmer Earth sends out more infrared, so the warming continues only until the balance returns. Scientists estimate that doubling carbon dioxide would eventually warm Earth by about 3 °C, probably between 2.5 °C and 4 °C. Each further doubling adds about the same amount again.','Will going from 556 to 1,112 ppm add more, less or the same warming as 278 to 556 ppm?','Read the eventual warming at 556 ppm and at 1,112 ppm.','Explain why the second doubling adds about the same warming as the first.'),
   st('Living things feel the change.','The air held about 278 ppm of carbon dioxide before industry and about 426 ppm in 2025. The rise of about 150 ppm comes mostly from burning coal, oil and gas, and partly from clearing forests. Scientists also checked natural causes: the energy arriving from the Sun has not increased since the 1950s, and volcanic eruptions cool Earth for only a year or two. Warming changes where plants and animals can grow and when they flower, breed or migrate. People can reduce emissions, for example by making electricity from sunlight and wind.','Name one change in temperature or rainfall that could affect a plant’s growth.','Set carbon dioxide to 426 ppm and read the eventual warming in this model.','Explain why the model’s eventual warming is not the warming measured so far.','The deep ocean takes centuries to warm, and the model ignores other gases and particles.')
  ],questions:[
   q('Earth absorbs more energy each second than it sends out to space. What happens to its average temperature?','It rises until the outgoing energy matches the incoming energy again.','It rises forever at the same rate.','It stays the same, because energy is conserved.','Extra energy kept each second warms Earth. A warmer Earth sends out more infrared, so the warming continues until the energy balance returns.'),
   q('In this model, carbon dioxide rising from 278 to 556 ppm gives about 3 °C of eventual warming. About how much more does 556 to 1,112 ppm add?','About 3 °C more','About 6 °C more','About 1.5 °C more','Each doubling of carbon dioxide adds about the same warming, so the second doubling adds about 3 °C more.'),
   q('Which action reduces the carbon dioxide that people add to the air?','Making electricity from sunlight instead of burning coal','Clearing forests for farmland','Burning more natural gas for heat','Solar electricity does not burn fuel. Clearing forests and burning fuel both add carbon dioxide.')],
  next:'Plot Earth’s yearly average temperature (from NASA or NOAA) and the yearly carbon dioxide measured at Mauna Loa since 1959. Describe each trend and its year-to-year ups and downs, and write one question about what causes them.'},
 {unit:'grade-7',segment:'Grade 7, instructional segment 1',pe:['MS-PS1-1','MS-PS1-4'],
  short:'Particles in motion',title:'What changes when a substance melts or boils?',goal:'Use a particle model to connect temperature, particle motion and state, and read a chemical formula as a count of atoms.',
  defaults:{substance:'water',temperature:25},controls:[pick('substance','Substance',[['water','Water, H₂O'],['oxygen','Oxygen, O₂'],['carbon-dioxide','Carbon dioxide, CO₂'],['methane','Methane, CH₄'],['ethanol','Ethanol, C₂H₆O']]),range('temperature','Temperature (°C)',-250,150,5)],
  steps:[
   st('Everything is made of atoms.','Atoms join into molecules. A water molecule, H₂O, has two hydrogen atoms and one oxygen atom: the small numbers in a formula count atoms, and a missing number means one. Some substances are not made of separate molecules. Table salt and diamond are extended structures: repeating patterns of particles that go on in every direction. This lab shows only substances made of molecules.','How many atoms are in one molecule of ethanol, C₂H₆O?','Choose ethanol and count the atoms in the drawing, then do the same for methane.','Explain how a chemical formula tells you which atoms are in one molecule, and how many.'),
   st('Temperature is particle motion.','The particles of every substance are always moving. In a solid they vibrate in place; in a liquid they slide past one another; in a gas they fly freely and collide. Temperature measures the average energy of this motion. Adding thermal energy makes the particles move faster on average, except while the substance is melting or boiling. At absolute zero, −273 °C, they would have the least motion possible.','Water is heated from 0 °C to 100 °C. Do its molecules move faster, slower or at the same speed?','Choose water and read the typical speed at 0 °C and at 100 °C.','Use the particle model to explain what a thermometer measures.'),
   st('Each substance changes state at its own temperature.','At the melting point, added energy loosens the attractions that hold particles in place, so the temperature stops rising until the change is complete, as in lesson 2. The particles of different substances attract one another with different strengths, so each substance melts and boils at its own temperature. At sea-level pressure, carbon dioxide skips the liquid state: solid “dry ice” turns straight into gas at −78.5 °C.','At −100 °C, which is a gas: oxygen, carbon dioxide or ethanol?','Set −100 °C and switch between oxygen, carbon dioxide and ethanol.','Explain why different substances melt and boil at different temperatures.'),
   st('Same temperature, different speeds.','At the same temperature, the particles of every substance have the same average energy of motion, but heavier molecules carry it at lower speeds. Masses are counted in atomic mass units: hydrogen 1, carbon 12, oxygen 16, so water has mass 18 and carbon dioxide 44. At 25 °C a water molecule has a typical speed of about 640 m/s, and a carbon dioxide molecule about 410 m/s.','At 25 °C, which moves faster: a water molecule or a carbon dioxide molecule?','Set 25 °C and compare water with carbon dioxide.','A smell spreads across a room far more slowly than its molecules move, which is hundreds of meters each second. Explain why.','Think about what the molecules keep bumping into, and how drafts carry them.')
  ],questions:[
   q('A sealed bottle of water is warmed from 20 °C to 80 °C. What happens to the water molecules?','They move faster on average; their number and size stay the same.','They get bigger.','New water molecules are made.','Warming adds energy of motion. The molecules themselves do not grow, and the sealed bottle holds the same number of them.'),
   q('At −100 °C and sea-level pressure, which of these is a gas?','Oxygen','Ethanol','Water','Oxygen boils at −183 °C, so at −100 °C it is a gas. Ethanol is a liquid between −114 °C and 78 °C, and water is ice below 0 °C.'),
   q('Oxygen, O₂, and carbon dioxide, CO₂, fill a room at 20 °C. Which statement is true?','Both have the same average energy of motion, but the lighter oxygen molecules move faster.','Carbon dioxide molecules move faster because they have more atoms.','Only the lighter molecules are moving.','Temperature sets the average energy of motion. Oxygen (mass 32) has a typical speed of about 480 m/s at 20 °C, and carbon dioxide (mass 44) about 410 m/s.')],
  next:'Stretch a balloon over the mouth of an empty bottle, stand the bottle in hot water and then in ice water, and explain what the balloon does with particle motion.'},
 {unit:'grade-7',segment:'Grade 7, instructional segment 2',pe:['MS-PS1-5','MS-LS1-6','MS-LS1-7'],
  short:'Atoms in living things',title:'Where does a tree’s mass come from?',goal:'Count atoms through photosynthesis, respiration and burning to show that matter is rearranged, not made or destroyed.',
  defaults:{reaction:'photosynthesis',times:1},controls:[pick('reaction','Reaction',[['photosynthesis','Photosynthesis'],['respiration','Cellular respiration'],['methane','Burning methane']]),range('times','Number of times the reaction happens',1,10)],
  steps:[
   st('A famous willow.','In the 1600s, Jan Baptist van Helmont planted a 5-pound willow in 200 pounds of dried soil and gave it only water. Five years later the tree weighed about 169 pounds, and the soil had lost only about 2 ounces. He concluded that the tree was made of water. Water is part of the answer, but most of a plant’s dry mass, the mass left when its water is removed, comes from carbon dioxide in the air. In photosynthesis, plants use energy from sunlight to make sugar from carbon dioxide and water: 6 CO₂ + 6 H₂O → C₆H₁₂O₆ + 6 O₂. They build wood and their other parts from that sugar.','Where does most of the mass of dry wood come from: the soil, the water or the air?','Choose photosynthesis and read how much of the sugar’s mass comes from atoms that were in carbon dioxide.','Explain why van Helmont’s soil barely changed.'),
   st('Count the atoms.','A chemical reaction rearranges atoms into new molecules. No atoms are made or destroyed, so every atom before the reaction is still there after it, and the total mass stays the same. The table in the lab counts the atoms for you; balancing equations and atomic masses come in high school.','In photosynthesis, are there more, fewer or the same number of oxygen atoms after the reaction?','Count the atoms of each element before and after, then make the reaction happen 5 times.','Explain why the total mass cannot change in a reaction.'),
   st('Food is fuel.','Plants and animals release the energy stored in sugar by cellular respiration: C₆H₁₂O₆ + 6 O₂ → 6 CO₂ + 6 H₂O. Its overall equation is photosynthesis written backward, but cells use different steps, and plants do both. An animal that eats a plant breaks its food molecules apart: some atoms are rebuilt into the animal’s own body as it grows, and some are used in respiration, releasing energy for movement and warmth and returning the atoms to the air as carbon dioxide and water.','When you breathe out carbon dioxide, where did its carbon atoms come from?','Choose cellular respiration and compare its atoms and masses with those of photosynthesis.','Trace one carbon atom from the air, into a plant, into an animal that eats it, and back into the air.'),
   st('Burning is fast rearranging.','Burning also rearranges atoms and releases energy, only faster. Methane, the main part of natural gas, burns with oxygen: CH₄ + 2 O₂ → CO₂ + 2 H₂O. The products are gases that drift away, so an open fire seems to destroy mass. In a sealed container the total mass does not change.','A candle burns inside a sealed jar on a balance. Does the reading go up, go down or stay the same?','Choose burning methane and compare the mass before and after.','Explain why a burning log seems to lose mass, but a sealed jar does not.')
  ],questions:[
   q('Where does most of the mass of dry wood come from?','Carbon dioxide from the air','Minerals from the soil','Sunlight','Most of a tree’s dry mass is carbon and oxygen atoms taken in as carbon dioxide during photosynthesis. Sunlight supplies energy, not atoms, and minerals from the soil make up only a small part.'),
   q('Photosynthesis turns 6 carbon dioxide molecules (2 oxygen atoms each) and 6 water molecules (1 oxygen atom each) into 1 sugar molecule (6 oxygen atoms) and 6 oxygen molecules (2 oxygen atoms each). How many oxygen atoms are there before and after?','18 before and 18 after','12 before and 6 after','18 before and 12 after','Before: 6 × 2 + 6 × 1 = 18. After: 6 + 6 × 2 = 18. The atoms are rearranged, not lost.'),
   q('A log burns completely and leaves a little ash. Where did most of its mass go?','Into the air, as carbon dioxide and water vapor','It was destroyed by the fire.','It turned into heat and light.','The log’s atoms combined with oxygen and left as gases. Heat and light are energy, not matter.')],
  next:'Put water and a fizzing antacid tablet in a zip-top bag on a kitchen scale, seal it, and compare the mass before and after the fizzing. Then repeat with the bag open.'},
 {unit:'grade-7',segment:'Grade 7, instructional segment 3',pe:['MS-ESS2-3','MS-ESS3-1'],
  short:'Moving plates',title:'How fast do plates move?',goal:'Use magnetic stripes on the seafloor to find how fast plates spread, and explain why plate motion leaves resources unevenly spread.',
  defaults:{rate:2.5,distance:50},controls:[range('rate','Spreading rate on each side (cm per year)',0.5,8,0.25),range('distance','Distance of a rock sample from the ridge (km)',0,200,5)],
  steps:[
   st('Stripes on the seafloor.','In the 1950s and 1960s, ships towing magnetometers, instruments that measure magnetism, mapped the ocean floor. They found stripes of stronger and weaker magnetism, in matching patterns on both sides of mid-ocean ridges. In 1963 Fred Vine and Drummond Matthews explained them. Earth’s magnetic field flips direction at irregular times, and lava that cools at a ridge records the field of its time, so the stripes are rock magnetized in alternating directions: a record of new seafloor forming at the ridge and moving away on both sides.','If new seafloor forms at the ridge and moves away, where is the youngest rock?','Move the rock sample from the ridge outward and read its age.','Explain why the stripes on the two sides of the ridge are mirror images.'),
   st('Speed from stripes.','Speed is distance divided by time. The field last flipped about 780,000 years ago, so the edges of the dark stripe around the ridge mark rock of that age. A plate moving 1 cm a year travels 10 km in a million years.','If the plates spread faster, will the stripes be wider or narrower?','Change the spreading rate from 1 cm to 5 cm per year and watch the stripes and the graph.','Explain how a geologist could find the spreading rate from a map of the stripes.'),
   st('An ocean from a crack.','Matching fossils on both sides of the South Atlantic, such as the freshwater reptile Mesosaurus, matching rock layers and the fit of the coastlines show that South America and Africa were once joined. The Atlantic is still widening at the Mid-Atlantic Ridge, by about 2.5 cm a year in total. At that speed, opening an ocean 4,000 km wide takes about 160 million years, close to the 130 to 200 million years that its rocks give for the Atlantic’s age.','At 1.25 cm per year on each side, how old is seafloor 100 km from the ridge?','Set the rate to 1.25 cm per year and the sample to 100 km.','Use the speed to explain how a crack in a continent can become an ocean.'),
   st('Plates also place resources.','Plate motion also decides where useful resources are found, so they are spread unevenly. In California, gold was deposited in veins, cracks filled with minerals, along the Sierra Nevada foothills, the Mother Lode, by hot water circulating deep in the crust while an ocean plate was sinking beneath the coast. The Geysers, north of San Francisco, is the world’s largest geothermal field: hot rock a few kilometers down, left by magma that rose there, boils underground water into steam. Oil in the Los Angeles Basin formed from the buried remains of tiny sea organisms, trapped in rock folded by the moving plates. Gold and oil took millions of years to form, so once they are used up they are gone. Today the Pacific Plate slides northwest past North America by about 5 cm a year, mostly along the San Andreas Fault.','Why is gold found in one belt of the Sierra Nevada foothills rather than everywhere?','Work it out: at 5 cm a year, how far does the Pacific Plate slide past North America in 1 million years? Use 1 cm per year = 10 km per million years.','Explain why mineral and energy resources are found in some places and not others, and why they can run out.')
  ],questions:[
   q('Fossils of Mesosaurus, a small freshwater reptile, are found in southern Africa and in South America, but not in between. Which explanation fits the evidence best?','The two continents were once joined and have since moved apart.','Mesosaurus swam across the Atlantic Ocean.','Rivers carried the fossils across the ocean.','A freshwater reptile could not cross an ocean. Its fossils, matching rock layers and the fit of the coastlines all show that South America and Africa were once joined.'),
   q('Seafloor 60 km from a ridge is 2 million years old. About how fast does that side move?','About 3 cm per year','About 30 cm per year','About 0.3 cm per year','60 km in 2 million years is 30 km per million years, and 10 km per million years is 1 cm per year, so the speed is about 3 cm per year.'),
   q('Why are gold, oil and geothermal energy found in some parts of California and not others?','Geologic processes such as plate motion, magma and hot water concentrated them in particular places.','They were once spread evenly, and people have used them up everywhere else.','They form wherever people drill deep enough.','Resources form where particular geologic processes acted, so their distribution is uneven.')],
  next:'On a world map of earthquakes and volcanoes, trace the plate boundaries. Then mark where fossils such as Mesosaurus and Glossopteris have been found and see which continents they connect.'},
 {unit:'grade-7',segment:'Grade 7, instructional segment 4',pe:['MS-LS2-4','MS-LS2-5'],
  short:'Recovering a population',title:'What limits a population, and how can it recover?',goal:'Model how a new predator changes a population, and compare recovery plans against criteria.',
  defaults:{eagles:50,plan:'none'},controls:[range('eagles','Foxes taken by eagles each year (%)',0,60,5),pick('plan','Recovery plan, from year 10',[['none','No plan'],['remove','Move the eagles away'],['release','Release 20 captive-bred foxes a year for 10 years'],['both','Both']])],
  steps:[
   st('A population at its limit.','A population grows when births outnumber deaths. Food, water, shelter and space are limited, so a population levels off at the largest size its environment can support: its carrying capacity. In this model, an island can support about 1,500 foxes.','With no predators, what happens to a fox population that is already at its carrying capacity?','Set the eagles to 0% and read the population over 40 years.','Explain what keeps the population from growing past 1,500.'),
   st('A new predator arrives.','On three of California’s Channel Islands, island foxes had few predators. In the 1990s golden eagles began nesting there, drawn by the piglets of feral pigs, farm pigs gone wild. Bald eagles, which probably kept golden eagles away, had disappeared by the 1960s, mainly because of the pesticide DDT. The golden eagles hunted foxes. In about six years, foxes fell from about 1,780 to 15 on Santa Rosa Island, from about 450 to 15 on San Miguel Island, and from about 1,400 to 55 on Santa Cruz Island. In the model, eagles arrive in year 5.','If eagles take half the foxes each year from year 5, about how many foxes will be left in year 10?','Set the eagles to 50% with no plan and read the population in year 10.','Use births and deaths to explain why the population falls.'),
   st('Compare two solutions.','Each of these islands has its own kind of island fox, found nowhere else, so saving them protects biodiversity. Wildlife managers judge solutions against criteria: how many foxes remain after 40 years, how quickly they return to 1,000, and whether the solution removes the cause. Solutions also face constraints: cost, time, and what the public will accept. In the model, one plan moves the eagles away; another releases 20 foxes raised in captivity each year for 10 years.','Which plan will restore the foxes better: releasing captive-bred foxes, or moving the eagles away?','With eagles at 50%, compare each plan’s population in year 40 and the year it returns to 1,000.','Use the criteria to argue which plan is better.'),
   st('What really happened.','The real recovery used several solutions together: golden eagles were caught and moved to the mainland, about 5,000 feral pigs were removed from Santa Cruz Island despite the cost and public objections, bald eagles were brought back, and captive-bred foxes were released. By 2015 the three islands held about 4,000 foxes. In 2016 their foxes were removed from the endangered species list, in what the US Fish and Wildlife Service called the fastest successful recovery of any mammal listed under the Endangered Species Act.','Why remove the feral pigs, if the eagles, not the pigs, were eating the foxes?','Set the plan to both and find the year the population returns to 1,000.','Describe how the pigs, the golden eagles, the bald eagles and the foxes are connected.')
  ],questions:[
   q('Deer in a valley are at their carrying capacity when a drought cuts their food in half. What most likely happens?','The population falls toward a new, lower carrying capacity.','The population stays the same, because the deer are already adapted to the valley.','The population grows, because there is less competition.','Carrying capacity depends on resources such as food. With less food, fewer deer survive, so the population falls until births and deaths balance again.'),
   q('In the model, eagles take half the foxes each year. Captive-bred foxes are released for ten years, but the eagles stay. What happens?','The population falls more slowly while foxes are released, then keeps falling after the releases stop.','The population returns to its carrying capacity.','The population keeps growing after the releases stop.','The releases add foxes but do not remove the cause. The eagles take more foxes each year than births and releases replace.'),
   q('In a different situation, two plans both bring the foxes back to 1,000 by year 25. Plan A releases foxes every year forever; Plan B removes the cause of the decline. Which is the better long-term solution?','Plan B, because the population can then stay up without ongoing help.','Plan A, because releasing foxes is always better than changing an ecosystem.','They are equal, because both reach 1,000.','A solution that removes the cause meets the long-term criterion: the population stays near its carrying capacity once the help stops.')],
  next:'Read the National Park Service’s pages on the island fox recovery. Draw a food web with foxes, golden eagles, bald eagles, feral pigs and the foxes’ food, and mark each link the recovery changed.'},
 {unit:'grade-8',segment:'Grade 8, instructional segment 1',pe:['MS-PS3-1','MS-PS2-2','MS-PS2-1'],
  short:'Speed and crashes',title:'Why does speed matter so much in a crash?',goal:'Relate kinetic energy to mass and speed, explain stopping distances with force and mass, and use Newton’s third law for a collision.',
  defaults:{mass:1500,speed:50,road:'dry',view:'distance'},controls:[range('mass','Mass of the vehicle (kg)',800,3000,100),range('speed','Speed (km/h)',10,130,5),pick('road','Road',[['dry','Dry'],['wet','Wet']]),pick('view','Graph',[['distance','Stopping distances'],['energy','Kinetic energy']])],
  steps:[
   st('Energy of motion.','A moving object has kinetic energy, measured here in kilojoules (kJ): kinetic energy = ½ × mass × speed². Doubling the mass doubles it, but doubling the speed makes it four times as large. In a crash, that energy goes into bending metal, breaking glass, heat and sound.','A car’s speed doubles from 50 km/h to 100 km/h. How many times as much kinetic energy does it have?','Set the graph to kinetic energy and the mass to 1,500 kg. Read the energy at 50 km/h and at 100 km/h, then change the mass and watch the curve.','Use the two graphs, energy against speed and energy against mass, to explain why speed matters more.'),
   st('Stopping takes distance.','To stop, the brakes must take away all of the car’s kinetic energy. First the driver needs about 1.5 seconds to react, and the car keeps going at the same speed: that is the reaction distance. Then the car brakes, and the braking distance grows with the square of the speed.','At 100 km/h, is the braking distance twice or four times the braking distance at 50 km/h?','Compare the reaction and braking distances at 50 km/h and at 100 km/h, then switch to a wet road.','Explain why braking distance grows faster than reaction distance as speed increases.'),
   st('Force, mass and change in motion.','A change in motion depends on the forces on an object and on its mass: a bigger force changes the motion more, and the same force changes a bigger mass less. The road’s grip, or friction, on the tires can be larger for a heavier vehicle, about in proportion to its weight. So in this model every vehicle slows at the same rate and needs the same braking distance, but a heavier one needs a bigger braking force, measured in kilonewtons (kN), thousands of newtons. Real heavy trucks need farther to stop, because their brakes and tires cannot use all of that grip.','A 3,000 kg SUV and a 1,000 kg car brake from the same speed on the same dry road. Which needs the bigger braking force?','At 50 km/h, compare 1,000 kg with 3,000 kg: read the braking force and the braking distance.','Use force and mass to explain why both stop in the same distance in this model.'),
   st('Equal and opposite.','When two objects collide, each pushes on the other with a force of the same size, in opposite directions: Newton’s third law. When a car and a heavier truck collide, both feel the same force, but the car, with less mass, changes speed much more. Crumple zones, seat belts and airbags make a stop take longer, which lowers the force on the people inside; a helmet does the same for a rider’s head.','A small car and a large truck collide head-on. Which one feels the larger force?','The lab cannot show a collision. Read the braking force for 3,000 kg at 50 km/h, then imagine that same force pushing on a 1,000 kg car: would the car’s speed change more or less than the truck’s?','Explain why the people in the small car are at greater risk, even though the forces are equal.','Think about which vehicle’s speed changes more.')
  ],questions:[
   q('A car’s speed doubles. How does its kinetic energy change?','It becomes four times as large.','It doubles.','It stays the same, because the mass does not change.','Kinetic energy = ½ × mass × speed², so doubling the speed multiplies it by 2 × 2 = 4.'),
   q('On a dry road, a car brakes to a stop from 50 km/h in about 14 m. About how far does it need to brake from 100 km/h on the same road?','About 55 m','About 28 m','About 14 m','Braking distance grows with the square of the speed: twice the speed needs four times the distance, 4 × 13.8 ≈ 55 m.'),
   q('A car and a truck collide head-on. Which statement is true?','Each pushes on the other with a force of the same size.','The truck pushes harder, because it is heavier.','The car pushes harder, because it is lighter.','Newton’s third law: the forces between two colliding objects are equal in size and opposite in direction. The lighter car changes speed more, because the same force changes a smaller mass more.')],
  next:'Roll a toy car down a ramp from three heights into a paper cup on a flat floor. Measure how far the cup slides each time, and compare it with the car’s speed at the bottom of the ramp.'},
 {unit:'grade-8',segment:'Grade 8, instructional segment 2',pe:['MS-ESS1-1','MS-PS2-4'],
  short:'Moon phases',title:'Why does the Moon change shape?',goal:'Use a model of the Sun, Earth and Moon to explain the Moon’s phases, when it rises and when eclipses happen, and describe gravity between Earth and the Moon.',
  defaults:{day:7.5},controls:[range('day','Days since new moon',0,29.5,0.5)],
  steps:[
   st('Half lit, always.','The Sun always lights half of the Moon; the Moon makes no light of its own. As the Moon orbits Earth, it takes about 29.5 days to go from one new moon to the next, and we see different amounts of its lit half.','At new moon, which half of the Moon is lit: the half facing Earth or the half facing away?','Set day 0 and look at the view from above: which half faces the Sun, and which half faces Earth?','Explain why we cannot see the Moon at new moon.'),
   st('Phases in order.','Between new moon and full moon, the lit part we see grows: the Moon is waxing. After full moon it shrinks: the Moon is waning. A crescent is less than half lit, and a gibbous Moon is more than half lit. From the Northern Hemisphere, a waxing Moon is lit on the right.','About how many days after new moon does full moon come?','Move the day slider and find when the lit part reaches 100%.','Explain why the phases repeat in the same order every month.'),
   st('When the Moon rises.','The Moon rises about 50 minutes later each day, because it moves along its orbit while Earth spins. A full moon is opposite the Sun, so it rises around sunset; a first-quarter moon rises around noon and is high in the south at sunset.','About what time does a full moon rise?','Read the rising time at first quarter, at full moon and at third quarter.','Use the view from above to explain why a full moon rises at sunset.'),
   st('Gravity and eclipses.','Gravity holds the Moon in its orbit. Any two objects with mass pull on each other: the pull is stronger when the masses are larger, and weaker when they are farther apart. Earth pulls on the Moon, and the Moon pulls back on Earth just as hard. The Moon’s pull is a little stronger on the side of Earth nearer to it, and that difference raises the ocean tides. The Moon’s orbit is tilted about 5° to the plane of Earth’s orbit around the Sun, so most months the Moon passes above or below the line from Earth to the Sun. An eclipse happens only when a new or full moon lines up closely with the Sun and Earth: a solar eclipse at new moon, a lunar eclipse at full moon.','Why is there not a solar eclipse at every new moon?','The view from above cannot show the 5° tilt. Set day 0 and then day 15, and say which kind of eclipse could happen at each if the line-up were close enough.','Earth and the Moon pull on each other equally hard. Explain why the Moon is the one that circles around.','Think about which object has less mass. Earth wobbles a little too: both circle a shared point inside Earth.')
  ],questions:[
   q('What causes the Moon’s phases?','As the Moon orbits Earth, we see different amounts of its sunlit half.','Earth’s shadow covers part of the Moon.','Clouds in space block part of the Moon.','The Sun always lights half of the Moon. The phase depends on how much of that lit half faces Earth. Earth’s shadow falls on the Moon only during a lunar eclipse.'),
   q('A full moon is rising. About what time is it?','Around sunset','Around noon','Around sunrise','A full moon is on the opposite side of Earth from the Sun, so it rises as the Sun sets.'),
   q('Which statement about gravity between Earth and the Moon is true?','Earth pulls on the Moon exactly as hard as the Moon pulls on Earth.','Only Earth pulls; the Moon has too little mass to pull.','The Moon pulls harder, because it is smaller.','Gravity is a pull between both objects, with forces of equal size. The Moon, with much less mass, is the one whose motion changes more. The Moon’s pull is stronger on Earth’s near side, and that difference raises the tides.')],
  next:'Starting a few days after new moon, look at the Moon at the same time each evening for two weeks. Sketch its shape and where it is in the sky, then match each sketch to a day in the lab.'},
 {unit:'grade-8',segment:'Grade 8, instructional segment 3',pe:['MS-LS4-4','MS-LS4-6','MS-LS3-1'],
  short:'Natural selection',title:'How does a rare trait become common?',goal:'Explain how a mutation can change a trait, and use a model to show how natural selection changes how common a trait is over many generations.',
  defaults:{ground:'lava',advantage:5,start:1},controls:[pick('ground','Ground',[['lava','Dark lava rock'],['sand','Pale sandy rock']]),range('advantage','Survival advantage of the better-matched color (%)',0,20,1),range('start','Dark mice at the start (%)',0,50,1)],
  steps:[
   st('Mice that match their rocks.','Rock pocket mice live in the deserts of the US Southwest and northern Mexico. Most are sandy-colored, but on dark lava flows in Arizona and New Mexico most are nearly black. Scientists think owls and other predators spot mice that stand out against the rock more easily, so mice that match their ground are more likely to survive and have young.','On a dark lava flow, which mice are more likely to survive and have young?','Set the ground to lava and watch the share of dark mice over 200 generations.','Explain why the share of dark mice changes, using survival and reproduction.'),
   st('A change in a gene.','In dark mice from one Arizona lava flow, scientists found changes, or mutations, in a gene called Mc1r. The gene carries the instructions for a protein that helps decide which pigment the fur makes, and the changed protein leads to dark fur. In dark mice from New Mexico, the dark fur comes from changes in other genes: the same trait evolved twice. A mutation can be harmful, helpful or neutral, depending on the environment.','Is the dark-fur mutation helpful, harmful or neutral?','Compare the share of dark mice after 100 generations on lava and on sand.','Explain why the same mutation can be helpful in one place and harmful in another.'),
   st('Small advantages add up.','In each generation, the better-matched mice leave slightly more young. The model raises their share a little each generation, so even a 5% advantage turns a rare color into the common one within about 150 generations.','With a 1% advantage instead of 5%, will dark fur take more or fewer generations to become common?','Set the advantage to 1% and then to 10%, and read the generation when dark mice pass half. At 1% it takes longer than the 200 generations shown.','Explain how a small advantage can change a population a lot over time.'),
   st('Selection needs variation.','Natural selection does not cause mutations. Variation comes first, from mutations and from the mixing of genes when parents have young; the environment then determines which variations help. If no mouse carried a dark-fur mutation, dark fur could not spread, however useful it would be.','If no mouse carries a dark-fur mutation, can the population turn dark on a new lava flow?','Set the advantage to 5% and compare starting shares of 0%, 1% and 50%.','Explain why natural selection can only work with variations that already exist.')
  ],questions:[
   q('Mostly dark mice live on dark lava, and mostly pale mice on pale rock nearby. Which is the best explanation?','Predators caught more of the mice that stood out, so mice that matched their ground left more young.','Each mouse changed its fur color to match the rock.','The dark rock stained the mice’s fur.','Individual mice do not change color. Over many generations, the mice whose inherited color matched the ground survived and reproduced more often.'),
   q('In the model, dark mice start at 1% on lava with a 5% advantage. About when do they pass half of the population?','After about 90 to 100 generations','After about 10 generations','Never, because a 5% advantage is too small','Each generation multiplies the ratio of dark to light mice by 1.05. Going from 1 to 99 to 1 to 1 takes about 94 generations.'),
   q('A mutation in the Mc1r gene gives a mouse dark fur. On pale rock, owls catch dark mice more often. What is the mutation’s effect there?','Harmful','Helpful','Neutral, because a mutation only changes a protein','The same change is helpful on dark lava and harmful on pale rock: whether a mutation helps depends on the environment.')],
  next:'Scatter equal numbers of dark and light paper dots on a dark sheet and on a light sheet. A partner picks up as many dots as possible in 10 seconds; count which colors are left on each sheet.'},
 {unit:'grade-8',segment:'Grade 8, instructional segment 4',pe:['MS-PS4-1','MS-PS4-2','MS-PS4-3'],
  short:'Listening with waves',title:'How do scientists listen to whales?',goal:'Describe waves with frequency, wavelength, speed and amplitude, and explain how sound is reflected, transmitted and recorded digitally.',
  defaults:{medium:'water',frequency:20,amplitude:1,samples:'off'},controls:[pick('medium','Material',[['air','Air, 343 m/s'],['water','Seawater, about 1,500 m/s'],['steel','Steel, about 5,960 m/s']]),range('frequency','Frequency (Hz)',10,150,10),range('amplitude','Amplitude',1,4,1),pick('samples','Digital samples',[['off','Hidden'],['on','Shown, one every 2 ms']])],
  steps:[
   st('Listening for whales.','Sound is a wave: a pattern of squeezed and stretched particles that travels through a material. Blue whales off California call at very low pitches, about 15 to 45 vibrations each second, or hertz (Hz), near the lowest pitch people can hear. Frequency is how many waves pass each second; wavelength is the distance from one wave to the next; and speed = frequency × wavelength.','A 20 Hz whale call travels through seawater at about 1,500 m/s. About how long is each wave?','Set seawater and 20 Hz and read the wavelength.','Explain how you can find a wavelength from the speed and the frequency.'),
   st('Same pitch, different materials.','Sound travels faster in water than in air, and faster still in steel. When sound passes into a new material, its frequency stays the same, so its wavelength changes.','Will a 20 Hz sound have a longer or a shorter wavelength in air than in seawater?','Keep 20 Hz and switch between air, seawater and steel.','Explain why the wavelength changes when the frequency does not.'),
   st('Bigger waves carry more energy.','Amplitude is the size of a wave: how strongly the particles are squeezed and stretched. A wave’s energy grows with the square of its amplitude, so twice the amplitude carries four times the energy. A louder sound has a larger amplitude.','If a call’s amplitude doubles, how many times as much energy does it carry?','Change the amplitude from 1 to 2 to 4 and read the energy.','Explain why a wave with a larger amplitude can travel farther before it fades.'),
   st('Reflect, transmit and record.','When a wave reaches a new material, part of it is reflected, part is absorbed and part passes through. Almost all of a sound in water bounces back off the sea surface, so people in a boat hear little of the whales below. Researchers listen with hydrophones, microphones that work underwater. One sits on the deep seafloor at the edge of Monterey Bay, about 900 m down, linked to shore by a cable. It records sound digitally: it measures the wave about 256,000 times each second and stores each measurement as a number. An analog recording instead stores a smooth copy of the wave’s shape, like the groove of a vinyl record or magnetic tape. Numbers can be copied and sent exactly, while an analog copy picks up a little noise each time it is copied.','Why do whale researchers put their microphones in the water rather than on a boat?','Show the digital samples and read the first few numbers a hydrophone would store for a 20 Hz call.','Explain why a digital recording of a whale call can be copied many times without getting worse.')
  ],questions:[
   q('A sound wave passes from air into water. What stays the same?','Its frequency','Its speed','Its wavelength','The source sets the frequency, so it stays the same. Sound is faster in water, so with the same frequency its wavelength is longer.'),
   q('A 30 Hz whale call travels through seawater at 1,500 m/s. What is its wavelength?','50 m','45,000 m','0.02 m','Wavelength = speed ÷ frequency = 1,500 ÷ 30 = 50 m.'),
   q('A whale call is copied 10 times, once as an analog recording and once as digital numbers. Which final copy is more likely to match the original?','The digital copy, because numbers can be copied exactly','The analog copy, because it keeps the smooth shape of the wave','Both, because copying never changes a recording','Each analog copy adds a little noise, and the noise builds up. Digital numbers are copied exactly, so the tenth copy matches the original recording.')],
  next:'Record a short sound with one phone, play it aloud and record it with a second phone, and repeat a few times. Compare the copies by ear, then explain why a digital file copied directly does not change.'}
];
function create(){
 const id='integrated-science';
 const lessons=clone(SPECS).map((s,i)=>{
  const tasks=s.questions.map((t,j)=>{const options=t.labels.map((label,k)=>({id:String(k),label})),rotate=(i+j)%3;return{id:id+'-l'+(i+1)+'-q'+(j+1),prompt:t.prompt,options:options.slice(rotate).concat(options.slice(0,rotate)),correct:['0'],explanation:t.explanation};});
  return{...s,id:id+'-lesson-'+(i+1),predict:tasks[0],checks:tasks.slice(1)};
 });
 // A record saved before a unit was added opens with the new lessons and every earlier answer kept.
 return{MODULE:id,TITLE:'Integrated Science 6–10',VERSION:'integrated-science-3',PREVIOUS:[{version:'integrated-science-1',lessons:4},{version:'integrated-science-2',lessons:8}],UNITS:clone(UNITS),summaryHeadline:'Connect the model\nto the world.',
  eyebrow:'INTEGRATED SCIENCE · GRADES 6–10',headline:'Build a model.\nTest it against the world.',
  lead:'Follow California’s integrated science from cells, weather, atoms, plates, forces and waves in grades 6 to 8 toward Living Earth and Chemistry in the Earth System, one model at a time.',
  prerequisite:'Use whole numbers, decimals, ratios, and simple formulas. Scientific relationships are supplied in each lesson.',
  scope:'Selected foundations: one lesson for each instructional segment of California’s integrated grades 6–8 and the Living Earth and Chemistry in the Earth System courses. Not a complete year of science or a laboratory program.',
  reportsHref:'../../reports/',LESSONS:lessons};
}
const api={create,UNITS,SPECS};
if(typeof module==='object'&&module.exports)module.exports=api;else root.QuidenceScienceContent=api;
})(typeof window==='undefined'?globalThis:window);
